import math

def tau(n):
    """Calculates the number of divisors of n (tau function)."""
    if n <= 0:
        return 0
    if n == 1:
        return 1

    count = 1
    n_copy = n
    i = 2
    while i * i <= n_copy:
        if n_copy % i == 0:
            exponent = 0
            while n_copy % i == 0:
                exponent += 1
                n_copy //= i
            count *= (exponent + 1)
        i += 1
    if n_copy > 1:
        count *= 2
    return count

